<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiClient, currentApiCacheScope } from '../../utils/api.js';
import { uploadListingMedia } from '../../api/tools/imageCropper';
const props=defineProps({shopId:{type:Number,default:null},shops:{type:Array,default:()=>[]},schema:{type:Object,required:true},templates:{type:Array,default:()=>[]},draft:{type:Object,default:null},card:{type:Object,default:null}}),emit=defineEmits(['close','saved','shop-changed']);
const clone=v=>JSON.parse(JSON.stringify(v));
const source=reactive({query:'',rows:[]}),targetShop=ref(props.draft?.target_shop_id||props.draft?.shop_id||props.shopId||null),previewVisible=ref(false),submitIntent=ref(false),savedShop=ref(props.draft?.shop_id||props.shopId||null);
const initial=props.draft?.payload||{subject_id:props.card?.subjectID||null,card:props.card?clone(props.card):{title:'',vendorCode:'',brand:'',description:'',dimensions:{length:null,width:null,height:null,weightBrutto:null},characteristics:[],sizes:[{techSize:'0',price:null,skus:[]}]},images:(props.card?.photos||[]).map(p=>p.big).filter(Boolean)};
const form=reactive({currency:'CNY',...clone(initial),template_id:Number(props.schema.template_id),subject_id:Number(props.schema.subject_id)}),draftId=ref(props.draft?.id||null),revision=ref(props.draft?.revision||1),busy=ref(false),attributes=ref([]),values=reactive({}),imageUrl=ref(''),dragIndex=ref(-1),errors=ref([]),barcodeText=ref(form.card.sizes.map(s=>(s.skus||[]).join('\n')));
for(const item of form.card.characteristics||[])values[item.id]=Array.isArray(item.value)?item.value.join(', '):item.value;
async function run(work){if(busy.value)return;busy.value=true;const scope=currentApiCacheScope();try{await work(scope);}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{busy.value=false;}}
function applyTemplate(clear=false){const template=props.templates.find(t=>Number(t.id)===Number(form.template_id));if(!template)return;form.subject_id=Number(template.subject_id);attributes.value=template.attributes||[];if(clear){for(const key of Object.keys(values))delete values[key];for(const value of template.defaults?.characteristics||[])values[value.id]=Array.isArray(value.value)?value.value.join(', '):value.value;}form.currency='CNY';}
const optionalLimit=ref(12);
const editableAttributes=computed(()=>attributes.value.filter(a=>!a.existNamedField&&Number(a.charcType)!==0&&Number(a.charcID)!==14177453));
const visibleAttributes=computed(()=>{const required=editableAttributes.value.filter(a=>a.required),optional=editableAttributes.value.filter(a=>!a.required);return [...required,...optional.slice(0,optionalLimit.value)];});
function payload(){const value=clone(form);value.card.sizes=value.card.sizes.map((s,i)=>({...s,skus:barcodeText.value[i].split(/\s+/).filter(Boolean)}));value.card.characteristics=attributes.value.map(a=>({id:a.charcID,value:Number(a.charcType)===4?(values[a.charcID]===undefined||values[a.charcID]===null||values[a.charcID]===''?undefined:Number(values[a.charcID])):String(values[a.charcID]||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)})).filter(a=>a.value!==undefined&&(!Array.isArray(a.value)||a.value.length));return value;}
async function findSource(){await run(async scope=>{const r=await apiClient.get(`/api/listing/drafts?paged=1&lightweight=1&pageSize=20&query=${encodeURIComponent(source.query)}`,{noCache:true});if(scope===currentApiCacheScope())source.rows=r.rows||[];});}
async function importSource(id){await run(async scope=>{const r=await apiClient.get(`/api/wb/listing-source?source_draft_id=${id}${targetShop.value?`&shop_id=${targetShop.value}`:''}`,{noCache:true});if(scope!==currentApiCacheScope())return;Object.assign(form,r);barcodeText.value=form.card.sizes.map(()=>'');for(const key of Object.keys(values))delete values[key];applyTemplate(true);ElMessage.info('已引用当前草稿图片与文案；请重新选择 WB 类目、核对车型、填写 WB 售价及条码。');});}
async function save(){if(!targetShop.value)throw Error('请在页面下方选择目标 WB 店铺，再保存商品草稿。');applyTemplate(false);let saveId=draftId.value;if(saveId&&Number(savedShop.value)!==Number(targetShop.value)){await ElMessageBox.confirm('目标店铺已改变，本次会保存为该店铺的新草稿，原店铺草稿保留。','保存新店铺草稿');saveId=null;}
 const r=await apiClient.post('/api/wb/listing-drafts/save',{shop_id:targetShop.value,draft_id:saveId,revision:revision.value,payload:payload()});draftId.value=r.draft_id;revision.value=r.revision;savedShop.value=targetShop.value;emit('saved');return r;}
async function saveOnly(){await run(async()=>{await save();ElMessage.success('WB 商品草稿已保存，未提交上架');});}
async function validate(){previewVisible.value=true;errors.value=[];await run(async scope=>{const r=await apiClient.post('/api/wb/listing-preview',{shop_id:targetShop.value,payload:payload()});if(scope!==currentApiCacheScope())return;errors.value=r.errors||[];if(r.ok)ElMessage.success('资料校验通过，尚未向 WB 提交');});}
async function reviewSubmission(){submitIntent.value=true;await validate();}
function addImage(){const url=imageUrl.value.trim();if(url&&!form.images.includes(url)&&form.images.length<30){form.images.push(url);imageUrl.value='';}}
function drop(index){const from=dragIndex.value;if(from>=0&&from!==index){const [image]=form.images.splice(from,1);form.images.splice(index,0,image);}dragIndex.value=-1;}
async function upload(options){await run(async scope=>{try{if(form.images.length>=30)throw Error('每个商品最多 30 张图片');const r=await uploadListingMedia(options.file,{source_module:'wb_listing',role:'listing_image'});if(scope!==currentApiCacheScope())return;if(r.mediaType!=='image'||!r.publishUrl)throw Error('图片未生成可公开读取的发布地址，请检查素材配置');form.images.push(r.publishUrl);options.onSuccess?.(r);}catch(e){options.onError?.(e);throw e;}});}
onMounted(()=>applyTemplate(!props.draft));
defineExpose({getContext:()=>({id:draftId.value,revision:revision.value,shop_id:savedShop.value,target_shop_id:targetShop.value,payload:payload()}),getPayload:payload,getShopId:()=>targetShop.value,saveDraft:saveOnly,preview:validate,reviewSubmission});
</script>
<template>
 <div class="wb-workbench-fields">
  <el-form label-width="116px" :disabled="busy" class="copy-form">
   <section class="editor-block"><h3>商品信息</h3><div class="form-shell">
    <el-form-item v-if="!draftId" label="引用商品资料"><div class="field-row"><el-input v-model="source.query" placeholder="输入已有草稿货号或名称" @keyup.enter="findSource"/><el-button @click="findSource">搜索草稿</el-button></div></el-form-item>
    <el-table v-if="source.rows.length" :data="source.rows" max-height="240"><el-table-column prop="internal_code" label="货号" width="160"/><el-table-column prop="product_name" label="商品"/><el-table-column width="80"><template #default="{row}"><el-button link type="primary" @click="importSource(row.id)">引用</el-button></template></el-table-column></el-table>
    <el-form-item label="商品标题" required><el-input v-model="form.card.title" :maxlength="60" show-word-limit/></el-form-item>
    <el-form-item label="商家货号" required><el-input v-model="form.card.vendorCode" :disabled="!!draftId||!!form.card.nmID" :maxlength="72" placeholder="vendorCode"/></el-form-item>
    <el-form-item label="品牌"><el-input v-model="form.card.brand"/></el-form-item>
    <el-form-item label="商品描述"><el-input v-model="form.card.description" type="textarea" :rows="5"/></el-form-item>
   </div></section>
   <section class="editor-block"><div class="section-line"><h3>WB 商品表格</h3><el-button :disabled="form.card.sizes.length>=30" @click="form.card.sizes.push({techSize:'',price:null,skus:[]});barcodeText.push('')">添加规格</el-button></div>
    <el-table :data="form.card.sizes" border stripe class="variant-table dense-variant-table" :scrollbar-always-on="true">
     <el-table-column type="index" label="序号" width="64" fixed="left"/>
     <el-table-column label="规格 / 尺码" min-width="180"><template #default="{row}"><el-input v-model="row.techSize" placeholder="无尺码填写 0"/></template></el-table-column>
     <el-table-column label="WB 尺码" min-width="140"><template #default="{row}"><el-input v-model="row.wbSize"/></template></el-table-column>
     <el-table-column label="售价（人民币 CNY）" min-width="180"><template #default="{row}"><el-input-number v-model="row.price" :min="1" :precision="0"/></template></el-table-column>
     <el-table-column label="商品条码" min-width="230"><template #default="{$index}"><el-input v-model="barcodeText[$index]" type="textarea" placeholder="每行一个条码；审核草稿可暂留空"/></template></el-table-column>
     <el-table-column label="操作" width="90"><template #default="{$index}"><el-button link type="danger" :disabled="form.card.sizes.length===1" @click="form.card.sizes.splice($index,1);barcodeText.splice($index,1)">删除</el-button></template></el-table-column>
    </el-table>
   </section>
   <section class="editor-block"><h3>商品属性</h3><div class="form-shell"><el-form-item v-for="attribute in visibleAttributes" :key="attribute.charcID" :label="attribute.name+(attribute.unitName?`（${attribute.unitName}）`:'')" :required="attribute.required"><el-input-number v-if="Number(attribute.charcType)===4" v-model="values[attribute.charcID]"/><el-input v-else v-model="values[attribute.charcID]" :placeholder="attribute.maxCount===1?'填写属性值':'多个值用逗号分隔'"/></el-form-item><el-button v-if="optionalLimit<editableAttributes.length" @click="optionalLimit+=12">展开更多选填属性</el-button><p v-if="!editableAttributes.length">此类目当前没有独立属性字段，请补全商品信息、规格和包装。</p></div></section>
   <section class="editor-block"><h3>包装信息</h3><div class="form-shell package-grid"><el-form-item v-for="(label,key) in {length:'包装长（cm）',width:'包装宽（cm）',height:'包装高（cm）',weightBrutto:'包装重量（kg）'}" :key="key" :label="label" required><el-input-number v-model="form.card.dimensions[key]" :precision="key==='weightBrutto'?3:0" :min="key==='weightBrutto'?0.001:1"/></el-form-item></div></section>
   <section class="editor-block"><h3>商品图片</h3><div class="form-shell"><div class="field-row"><el-upload :show-file-list="false" :http-request="upload" accept="image/*" :disabled="busy"><el-button>上传图片</el-button></el-upload><el-input v-model="imageUrl" placeholder="填写 HTTPS 图片直链" @keyup.enter="addImage"/><el-button @click="addImage">添加图片</el-button></div><p class="field-hint">第一张为主图；拖动调整顺序，点击图片预览。最多 30 张。</p><div class="wb-images"><div v-for="(image,index) in form.images" :key="index" draggable="true" @dragstart="dragIndex=index" @dragover.prevent @drop.prevent="drop(index)" @dragend="dragIndex=-1"><el-image :src="image" :preview-src-list="form.images" :initial-index="index" preview-teleported fit="cover"/><span>{{index===0?'主图':`图片 ${index+1}`}}</span><el-button link type="danger" @click="form.images.splice(index,1)">删除</el-button></div></div></div></section>
   <section class="editor-block"><h3>上架设置</h3><div class="form-shell"><el-form-item label="上架店铺" required><el-select v-model="targetShop" @change="id=>{if(shops.find(s=>Number(s.id)===Number(id))?.environment!==schema.environment)emit('shop-changed');}" filterable placeholder="填写完成后选择目标 WB 店铺"><el-option v-for="shop in shops" :key="shop.id" :value="Number(shop.id)" :label="shop.name"/></el-select></el-form-item><p class="field-hint">WB 售价独立使用人民币。物流费用和利润规则待接入，不套用 Ozon 公式。</p><el-alert v-for="note in form.review_notes||[]" :key="note" :title="note" type="warning" :closable="false"/></div></section>
  </el-form>
  <el-drawer v-if="previewVisible" :model-value="true" title="WB 上架预览与校验" size="min(900px,95vw)" @close="previewVisible=false;submitIntent=false"><el-alert title="待你审核，当前商品尚未向 WB 提交" type="info" :closable="false"/><el-alert v-if="submitIntent" title="本轮仍保持发布开关关闭；确认商品内容后再开放正式提交。" type="warning" :closable="false"/><h3>{{form.card.title||'未填写标题'}}</h3><p>类目：{{schema.category_name}}　货号：{{form.card.vendorCode}}</p><p>上架店铺：{{shops.find(s=>Number(s.id)===Number(targetShop))?.name||'待选择'}}</p><p>售价：{{form.card.sizes.map(s=>`¥ ${s.price??'待填写'} CNY`).join(' / ')}}</p><p class="description">{{form.card.description}}</p><div class="preview-images"><el-image v-for="(image,index) in form.images" :key="index" :src="image" :preview-src-list="form.images" :initial-index="index" preview-teleported fit="contain"/></div><el-alert v-for="error in errors" :key="error" :title="error" type="warning" :closable="false"/><el-button type="primary" :loading="busy" @click="saveOnly">保存为草稿</el-button></el-drawer>
 </div>
</template>
<style scoped>
.copy-form{display:flex;flex-direction:column}.editor-block{padding:28px 0 14px}.editor-block+.editor-block{margin-top:12px}.editor-block h3{margin:0 0 22px;font-size:18px;line-height:1.2;text-align:center;font-weight:700;color:var(--erp-detail-text-main,#111827)}.form-shell{max-width:760px;margin:0 auto}.form-shell :deep(.el-form-item){margin-bottom:18px}.form-shell :deep(.el-form-item__label){justify-content:flex-end;color:var(--erp-detail-text-main,#1f2937);font-size:13px}.form-shell :deep(.el-select){width:100%}.field-row{display:flex;align-items:center;gap:8px;width:100%}.field-hint{font-size:12px;color:var(--el-text-color-secondary)}.section-line{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.section-line h3{margin:0}.wb-images{display:flex;flex-wrap:wrap;gap:14px;margin:16px 0}.wb-images>div{width:100px;display:grid;gap:6px;cursor:grab}.wb-images .el-image{width:100px;height:132px;border-radius:var(--el-border-radius-base)}.preview-images{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.preview-images .el-image{width:160px;height:210px}.description{white-space:pre-wrap;line-height:1.7}.variant-table :deep(.el-input-number){width:150px}@media(max-width:700px){.field-row{flex-wrap:wrap}}
</style>
